const {chromium}=require('playwright');
const BASE='http://localhost:8765/legion-takehome/';
(async()=>{const b=await chromium.launch();const ctx=await b.newContext();
const seen=new Set(),queue=[BASE],out=[];
while(queue.length){const u=queue.shift();if(seen.has(u))continue;seen.add(u);
  const p=await ctx.newPage();const errs=[],fails=[];
  p.on('pageerror',e=>errs.push(e.message));p.on('console',m=>{if(m.type()==='error')errs.push(m.text())});
  p.on('requestfailed',r=>{if(!/fonts\.g/.test(r.url()))fails.push(r.url())});
  p.on('response',r=>{if(r.url().startsWith('http://localhost')&&r.status()>=400)fails.push(r.status()+' '+r.url())});
  const res=await p.goto(u);const links=await p.$$eval('a[href]',as=>as.map(a=>a.href));
  out.push([u.replace(BASE,'/'),res.status(),errs.filter(e=>!/fonts|ERR_/.test(e)),fails]);
  for(const l of links){const c=l.split('#')[0];if(c.startsWith(BASE)&&!seen.has(c)){
    if(c.endsWith('.html')||c.endsWith('/'))queue.push(c);else{const r=await ctx.request.get(c);out.push([c.replace(BASE,'/'),r.status(),'(file)']);seen.add(c);}}}
  await p.close();}
for(const o of out)console.log(JSON.stringify(o));
// external link targets used
await b.close();})();
EOF
